CmdResult handleUnregisteredSaslAuth(const std::vector<std::string>& parameters, User* user) {
    if (!user->isUnregistered())
        return CMD_FAILURE;

    if (!user->hasCap("sasl"))
        return CMD_FAILURE;

    if (parameters.empty() || parameters[0].empty())
        return CMD_FAILURE;

    std::string mechanism = parameters[0];
    std::transform(mechanism.begin(), mechanism.end(), mechanism.begin(), ::toupper);

    if (user->saslAuthenticator) {
        if (!user->saslAuthenticator->sendClientMessage(parameters))
            return CMD_FAILURE;
    }
    else {
        user->saslAuthenticator = std::make_unique<SaslAuthenticator>(mechanism);
        if (!user->saslAuthenticator->sendClientMessage(parameters)) {
            user->announce("SASL authentication failed.");
            user->saslAuthenticator.reset();
            return CMD_FAILURE;
        }
    }

    return CMD_SUCCESS;
}

CmdResult handleUnregisteredSaslAuthentication(const std::vector<std::string>& parameters, User* user) {
    if (user->isRegistered()) {
        return CMD_FAILURE;
    }

    if (!user->hasCapability("sasl")) {
        user->writeNumeric(ERR_SASL_NOCAPABILITY, "SASL is not available for this user.");
        return CMD_FAILURE;
    }

    if (parameters.empty() || parameters[0].empty()) {
        user->writeNumeric(ERR_SASL_MALFORMED, "Authentication parameters are malformed.");
        return CMD_FAILURE;
    }

    const std::string& saslMechanism = parameters[0];

    if (!user->saslAuthenticator) {
        user->saslAuthenticator = createSaslAuthenticator(saslMechanism);
        if (!user->saslAuthenticator) {
            user->writeNumeric(ERR_SASL_UNKNOWNMECHANISM, "Unknown SASL mechanism: {}", saslMechanism);
            return CMD_FAILURE;
        }
    }

    if (!user->saslAuthenticator->sendClientMessage()) {
        user->writeNumeric(RPL_SASL_LOG, "SASL authentication failed.");
        user->saslAuthenticator.reset();
        return CMD_FAILURE;
    }

    return CMD_SUCCESS;
}

CmdResult handleUnregisteredClientSASLAuth(const std::vector<std::string>& parameters, User* user) {
    if (!user->isUnregistered()) {
        return CMD_FAILURE;
    }

    if (!user->hasCapabilities({"sasl"})) {
        return CMD_FAILURE;
    }

    if (parameters.empty() || parameters[0].empty()) {
        return CMD_FAILURE;
    }

    if (!user->getSASLAuthenticator()) {
        user->setSASLAuthenticator(std::make_unique<SASLAuthenticator>());
    }

    auto authenticator = user->getSASLAuthenticator();
    if (!authenticator->sendClientMessage(parameters[0])) {
        user->announce("AUTHENTICATOR_ERROR");
        user->unsetSASLAuthenticator();
        return CMD_FAILURE;
    }

    return CMD_FAILURE; // Authentication process not completed successfully
}

CmdResult handleUnregisteredClientAuthSASL(const std::vector<std::string>& parameters, User* user) {
    if (!user->isUnregistered())
        return CMD_FAILURE;

    if (!user->hasCap("sasl"))
        return CMD_FAILURE;

    if (parameters.empty() || parameters[0].empty())
        return CMD_FAILURE;

    if (!user->saslAuthenticator) {
        user->saslAuthenticator = new SASLAuthenticator(user);
    }

    if (!user->saslAuthenticator->sendClientMessage(parameters[0])) {
        user->write("AUTHENTICATE +");
        delete user->saslAuthenticator;
        user->saslAuthenticator = nullptr;
        return CMD_FAILURE;
    }

    return CMD_SUCCESS;
}

CmdResult handleUnregisteredSASLAuth(const std::vector<std::string>& parameters, User* user) {
    if (user->isRegistered()) {
        return CMD_FAILURE;
    }

    if (!user->hasCap("sasl")) {
        return CMD_FAILURE;
    }

    if (parameters.empty() || parameters[0].empty()) {
        return CMD_FAILURE;
    }

    std::string method = parameters[0];
    if (method != "PLAIN" && method != "EXTERNAL") {
        return CMD_FAILURE;
    }

    if (!user->saslAuth) {
        user->saslAuth = std::make_unique<SASLAuthenticator>(user, method);
    } else if (!user->saslAuth->sendClientMessage(parameters)) {
        user->sendAnnounce("SASL authentication failed.");
        user->saslAuth.reset();
        return CMD_FAILURE;
    }

    return CMD_FAILURE;
}
